 // \u8fdb\u884c\u52a0\u6cd5\u8fd0\u7b97\r\n  const sum = bigInt1 + bigInt2\r\n\r\n  // \u5c06\u7ed3\u679c\u8f6c\u6362\u4e3a\u5b57\u7b26\u4e32\r\n  return sum.toString()\r\n}\r\n\r\n// \u6d4b\u8bd5\u51fd\u6570\r\nconst num1 = '123456789012345678901234567890'\r\nconst num2 = '987654321098765432109876543210'\r\nconst sum = addLargeNumbers(num1, num2)\r\n\r\nconsole.log(sum) // \u8f93\u51fa \"1111111110111111111011111111100\"\n"})}),"\n",(0,t.jsx)(r.pre,{children:(0,t.jsx)(r.code,{className:"language-js",metastring:'showLineNumbers title="\u5b58\u50a8\u8fdb\u4f4d\u8fdb\u884c\u8fd0\u7b97"',children:"function addLargeNumbers(num1, num2) {\r\n  // \u786e\u4fdd num1 \u548c num2 \u90fd\u662f\u5b57\u7b26\u4e32\r\n  num1 = num1.toString()\r\n  num2 = num2.toString()\r\n\r\n  // \u521d\u59cb\u5316\u7ed3\u679c\u6570\u7ec4\u548c\u8fdb\u4f4d\r\n  let result = []\r\n  let carry = 0\r\n\r\n  // \u83b7\u53d6\u4e24\u4e2a\u6570\u5b57\u7684\u957f\u5ea6\r\n  let len1 = num1.length\r\n  let len2 = num2.length\r\n\r\n  // \u8ba1\u7b97\u6700\u957f\u7684\u957f\u5ea6\r\n  let maxLen = Math.max(len1, len2)\r\n\r\n  // \u4ece\u53f3\u5230\u5de6\u9010\u4f4d\u76f8\u52a0\r\n  for (let i = 0; i < maxLen; i++) {\r\n    // \u83b7\u53d6\u5f53\u524d\u4f4d\u7684\u6570\u5b57\uff0c\u5982\u679c\u957f\u5ea6\u4e0d\u8db3\u5219\u8865 0\r\n    let digit1 = i < len1 ? parseInt(num1[len1 - 1 - i]) : 0\r\n    let digit2 = i < len2 ? parseInt(num2[len2 - 1 - i]) : 0\r\n\r\n    // \u8ba1\u7b97\u5f53\u524d\u4f4d\u7684\u548c\r\n    let sum = digit1 + digit2 + carry\r\n\r\n    // \u8ba1\u7b97\u65b0\u7684\u8fdb\u4f4d\r\n    carry = Math.floor(sum / 10)\r\n\r\n    // \u5c06\u5f53\u524d\u4f4d\u7684\u7ed3\u679c\u5b58\u5165\u7ed3\u679c\u6570\u7ec4\r\n    result.push(sum % 10)\r\n  }\r\n\r\n  // \u5982\u679c\u6700\u540e\u8fd8\u6709\u8fdb\u4f4d\uff0c\u5219\u6dfb\u52a0\u5230\u7ed3\u679c\u6570\u7ec4\u4e2d\r\n  if (carry > 0) {\r\n    result.push(carry)\r\n  }\r\n\r\n  // \u5c06\u7ed3\u679c\u6570\u7ec4\u53cd\u8f6c\u5e76\u8f6c\u6362\u4e3a\u5b57\u7b26\u4e32\r\n  return result.reverse().join('')\r\n}\r\n\r\n// \u6d4b\u8bd5\u51fd\u6570\r\nconst num1 = '123456789012345678901234567890'\r\nconst num2 = '987654321098765432109876543210'\r\nconst sum = addLargeNumbers(num1, num2)\r\n\r\nconsole.log(sum) // \u8f93\u51fa \"1111111110111111111011111111100\"\n"})}),"\n",(0,t.jsx)(r.h2,{id:"js-\u8f6c\u6362\u5bf9\u8c61\u6210\u4e3a\u6811\u7ed3\u6784",children:"JS \u8f6c\u6362\u5bf9\u8c61\u6210\u4e3a\u6811\u7ed3\u6784"}),"\n",(0,t.jsx)(r.pre,{children:(0,t.jsx)(r.code,{className:"language-js",metastring:'showLineNumbers title="\u5229\u7528map\u904d\u5386\u6570\u7ec4\u6210\u4e3a\u6811\u7ed3\u6784"',children:"const flatArray = [\r\n  { id: 1, parentId: null, name: 'root1' },\r\n  { id: 2, parentId: 1, name: 'child1' },\r\n  { id: 3, parentId: 1, name: 'child2' },\r\n  { id: 4, parentId: 2, name: 'grandchild1' },\r\n  { id: 5, parentId: 3, name: 'grandchild2' }\r\n]\r\n\r\nfunction arrayToTree(items) {\r\n  const map = new Map()\r\n  const result = []\r\n\r\n  // \u521b\u5efa\u4e00\u4e2a map\uff0c\u65b9\u4fbf\u540e\u7eed\u67e5\u627e\u8282\u70b9\r\n  items.forEach(item => {\r\n    map.set(item.id, { ...item, children: [] })\r\n  })\r\n\r\n  items.forEach(item => {\r\n    const node = map.get(item.id)\r\n    if (item.parentId === null) {\r\n      // \u5982\u679c\u662f\u6839\u8282\u70b9\uff0c\u76f4\u63a5\u6dfb\u52a0\u5230 result\r\n      result.push(node)\r\n    } else {\r\n      // \u5982\u679c\u6709\u7236\u8282\u70b9\uff0c\u627e\u5230\u7236\u8282\u70b9\u5e76\u5c06\u5f53\u524d\u8282\u70b9\u52a0\u5165\u5176 children \u6570\u7ec4\r\n      const parentNode = map.get(item.parentId)\r\n      if (parentNode) {\r\n        parentNode.children.push(node)\r\n      }\r\n    }\r\n  })\r\n\r\n  return result\r\n}\r\n\r\nconst tree = arrayToTree(flatArray)\r\nconsole.log(JSON.stringify(tree, null, 2))\n"})}),"\n",(0,t.jsx)(r.pre,{children:(0,t.jsx)(r.code,{className:"language-js",metastring:'showLineNumbers title="\u5229\u7528\u9012\u5f52\u5b9e\u73b0"',children:"const flatArray = [\r\n  { id: 1, parentId: null, name: 'root1' },\r\n  { id: 2, parentId: 1, name: 'child1' },\r\n  { id: 3, parentId: 1, name: 'child2' },\r\n  { id: 4, parentId: 2, name: 'grandchild1' },\r\n  { id: 5, parentId: 3, name: 'grandchild2' }\r\n]\r\n\r\nfunction arrayToTree(array, parentId = null) {\r\n  return array\r\n    .filter(item => item.parentId === parentId)\r\n    .map(item => ({\r\n      ...item,\r\n      children: arrayToTree(array, item.id)\r\n    }))\r\n}\r\n\r\n// \u6d4b\u8bd5\u51fd\u6570\r\nconst tree = arrayToTree(flatArray)\r\nconsole.log(JSON.stringify(tree, null, 2)) // \u8f93\u51fa\u7ed3\u679c stringify\u7684\u4e09\u4e2a\u53c2\u6570\uff0c\u7b2c\u4e00\u4e2a\u662fjson\u5bf9\u8c61\uff0c\u7b2c\u4e8c\u4e2a\u662f replacer\uff0c\u7b2c\u4e09\u4e2a\u662f\u7f29\u8fdb\u7a7a\u683c\u6570\n"})}),"\n",(0,t.jsx)(r.h2,{id:"\u89e3\u6790-url",children:"\u89e3\u6790 url"}),"\n",(0,t.jsx)(r.pre,{children:(0,t.jsx)(r.code,{className:"language-js",metastring:'showLineNumbers title="\u5229\u7528URLSearchParams\u89e3\u6790url"',children:"// \u5b9a\u4e49\u89e3\u6790\u51fd\u6570\r\nfunction parseUrlParams(url) {\r\n  // \u521b\u5efa URL \u5bf9\u8c61\r\n  const urlObj = new URL(url)\r\n\r\n  // \u521b\u5efa URLSearchParams \u5bf9\u8c61\r\n  const params = new URLSearchParams(urlObj.search)\r\n\r\n  // \u521d\u59cb\u5316\u5b58\u50a8\u7ed3\u679c\u7684\u5bf9\u8c61\r\n  const result = {}\r\n\r\n  // \u904d\u5386 URLSearchParams \u5bf9\u8c61\r\n  for (const [key, value] of params.entries()) {\r\n    result[key] = value\r\n  }\r\n\r\n  return result\r\n}\r\n\r\n// \u6d4b\u8bd5\u89e3\u6790\u51fd\u6570\r\nconst url = 'https://example.com?name=yupi&age=25&location=shanghai'\r\nconst parsedParams = parseUrlParams(url)\r\n\r\nconsole.log(parsedParams)\r\n// \u8f93\u51fa\u7ed3\u679c\u5982\u4e0b\r\n// {\r\n//     name: 'yupi',\r\n//     age: '25',\r\n//     location: 'shanghai'\r\n// }\n"})}),"\n",(0,t.jsx)(r.h2,{id:"\u53cc\u5411\u657